---
// Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync.
// Tooltip: Quiet labels on hover, with shortcuts and a richer preview card.
// The markup, CSS and script are designme.dev's own, run by the shared core in ../core, which mounts the component when it scrolls
// into view and plays its demo. To show your own data, change tooltip.js. The markup is kept exactly as it is (is:raw).
import type { HTMLAttributes } from 'astro/types';
import '../core/designme.css';
import './tooltip.css';

export interface Props extends HTMLAttributes<'div'> {
  /** "soft" draws it in the Soft style. Leave it out for Blueprint, or for the style set on <html> (data-style="soft") */
  'data-style'?: 'soft';
}
const { class: className, ...rest } = Astro.props;
---
<div class:list={['card', className]} data-c="tooltip" {...rest}>
  <div class="stage-in"><Fragment is:raw>
<div class="ttp">
  <div class="ttp-bar panel">
    <button class="ib" aria-label="Undo" data-tip="Undo" data-tip-k="⌘Z"><svg class="i s"><use href="#i-undo"/></svg></button>
    <button class="ib" aria-label="Comment" data-tip="Comment" data-tip-k="C"><svg class="i s"><use href="#i-edit"/></svg></button>
    <button class="ib" aria-label="Ask agent" data-tip="Ask the agent" data-tip-k="⌘J"><svg class="i s"><use href="#i-spark"/></svg></button>
    <span class="ttp-sep"></span>
    <button class="ib" aria-label="Share" data-tip="Share with your team"><svg class="i s"><use href="#i-users"/></svg></button>
    <span class="ttp-sep"></span>
    <span class="ttp-avs"><button class="ttp-av" data-card="0"><span class="av" style="background:var(--dm-av-l);color:var(--dm-av-l-ink)">MK</span></button><button class="ttp-av" data-card="1"><span class="av" style="background:var(--dm-av-b);color:var(--dm-av-b-ink)">DA</span></button></span>
  </div>
  <div class="ttp-card panel"><div class="ttp-ci"></div></div>
  <p class="muted ttp-n">Labels wait a moment, then follow you instantly between buttons.</p>
</div>
  </Fragment></div>
</div>
<script>
  import './tooltip.js';
</script>

/* Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync. */
/* ---------- Tooltip ---------- */
.ttp{display:flex;flex-direction:column;align-items:center;gap:var(--dm-s-4);position:relative;min-height:200px;justify-content:center}
.ttp-bar{display:flex;align-items:center;gap:2px;padding:5px;border-radius:var(--dm-r-pill)}
.ttp-sep{width:1px;height:18px;background:var(--dm-line);margin:0 var(--dm-s-1)}
.ttp-avs{display:flex;padding-right:3px}
.ttp-av{border-radius:50%;margin-left:-4px;transition:transform .3s var(--dm-ease)}
.ttp-av:first-child{margin-left:0}
@media (hover:hover) and (pointer:fine){.ttp-av:hover{transform:translateY(-2px)}}
.ttp-av .av{width:28px;height:28px;font-size:11px;box-shadow:0 0 0 2px var(--dm-surface)}
.ttp-card{position:absolute;top:0;left:0;width:230px;padding:var(--dm-s-3);box-shadow:var(--dm-shadow-pop);opacity:0;transform:translateY(6px) scale(.97);filter:blur(4px);pointer-events:none;transition:opacity .25s var(--dm-ease),transform .35s var(--dm-ease),filter .25s;z-index:5}
.ttp-card.show{opacity:1;transform:none;filter:none}
.ttp-ch{display:flex;align-items:center;gap:10px}
.ttp-ch .av{width:34px;height:34px;font-size:12px}
.ttp-ch div{display:flex;flex-direction:column;font-size:13px}
.ttp-ch b{font-weight:500}
.ttp-ch div span{font-size:12px;color:var(--dm-muted)}
.ttp-cs{display:flex;align-items:center;gap:6px;margin-top:10px;font-size:12px;color:var(--dm-fg2)}
.ttp-cs .dot{color:var(--dm-ok)}
.ttp-n{font-size:12.5px;text-align:center}

// Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync.
import { $, $$, AV, DM, I, hideTip, showTip, tipFor, tipNext } from '../core/core.js';
DM.def('tooltip', (r, c) => {
  r.innerHTML = r.innerHTML.replace('{undo}', I('undo')).replace('{chat}', I('edit')).replace('{spark}', I('spark')).replace('{users}', I('users')).replace('{a1}', AV('MK','var(--dm-av-l)')).replace('{a2}', AV('DA','var(--dm-av-b)'));
  const P = [['MK','var(--dm-av-l)','Maya Kim','Design lead','Editing Pricing, frame 2'],['DA','var(--dm-av-b)','Design agent','Working for Maya','Auditing contrast, 2 of 6 checks']];
  const card = $('.ttp-card', r), ci = $('.ttp-ci', r), root = $('.ttp', r); let t;
  $$('.ttp-av', r).forEach(b => { b.onmouseenter = () => { clearTimeout(t); t = setTimeout(() => { const p = P[+b.dataset.card];
      ci.innerHTML = `<div class="ttp-ch">${AV(p[0], p[1])}<div><b>${p[2]}</b><span>${p[3]}</span></div></div><div class="ttp-cs">${p[0] === 'DA' ? '<span class="think on" style="color:var(--dm-accent-mark,var(--dm-accent))"><i></i><i></i><i></i><i></i></span>' : '<span class="dot"></span>'}${p[4]}</div>`;
      const rr = root.getBoundingClientRect(), br = b.getBoundingClientRect(); let x = br.left - rr.left + br.width / 2 - 115; x = Math.max(0, Math.min(x, rr.width - 230));
      card.style.left = x + 'px'; card.style.top = (br.bottom - rr.top + 10) + 'px'; card.classList.add('show'); }, 300); };
    b.onmouseleave = () => { clearTimeout(t); card.classList.remove('show'); }; });
  c.offs.push(() => clearTimeout(t));
  // once it has entered, it shows what it does: a shortcut tip, then the agent's card. Pointing at it takes over, as does
  // clicking, focusing or typing in it
  // what the demo opened goes when the pointer comes in, unless it is on that very control: the visitor's own hover decides
  // from then on, so no tip or card is left over from the demo over the one they point at
  let touched = false, shown = null;
  c.on(root, 'pointerenter', () => { touched = true;
    if (shown === 'tip' && tipFor && !tipNext && root.contains(tipFor) && !tipFor.matches(':hover')) hideTip();
    if (shown === 'card' && !$('.ttp-av:hover', r)){ clearTimeout(t); card.classList.remove('show'); }
    shown = null; });
  const go = () => { if (touched || c.mine) throw 'stop'; };
  c.run(async () => {
    await c.wait(1300); go(); if (tipFor) return;
    const ask = $('[data-tip-k="⌘J"]', r); showTip(ask); shown = 'tip'; await c.wait(1700); go(); if (tipFor === ask) hideTip(true); shown = null;
    await c.wait(500); go();
    const av = $('.ttp-av[data-card="1"]', r); av.onmouseenter(); shown = 'card'; await c.wait(2600); go(); av.onmouseleave(); shown = null;
  });
});
